import re

def parse(lines):
    recs = []
    used = []
    skip = []
    cur = None
    for i, l in enumerate(lines):
        if not l.strip():
            continue
        if re.match(r'^\[[^\]]*\]', l):
            skip.append(i)
            continue
        if l[0] in ' \t':
            m = re.match(r'^\s+(?P<key>[^:]+?):\s?(?P<value>.*)$', l)
            if m and cur is not None:
                cur[m.group('key').strip()] = m.group('value').strip()
                used.append(i)
            continue
        cur = {'Device': l.strip()}
        recs.append(cur)
        used.append(i)
    keys = []
    for r in recs:
        for k in r:
            if k not in keys:
                keys.append(k)
    rows = [{k: r.get(k, '') for k in keys} for r in recs]
    blocks = []
    if rows:
        blocks.append({'name': 'devices', 'kind': 'table', 'lines': used, 'records': rows})
    return {'blocks': blocks, 'skip': skip}
